CREATE TRIGGER drinks_fts_insert AFTER INSERT ON drinks BEGIN
  DELETE FROM drinks_fts WHERE drink_id = new.id;
  INSERT INTO drinks_fts (drink_id, name, producer, appellation, region, country, grapes, type_name, characteristics)
  SELECT d.id, d.name, d.producer, d.appellation, d.region, d.country, d.grapes,
    (SELECT t.name FROM drink_types t WHERE t.id = d.type_id AND t.deleted_at IS NULL),
    (SELECT group_concat(c.name, ' ') FROM drink_characteristics dc
       JOIN characteristics c ON c.id = dc.characteristic_id
       WHERE dc.drink_id = d.id AND dc.deleted_at IS NULL AND c.deleted_at IS NULL)
  FROM drinks d WHERE d.id = new.id;
END;

